import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Ένταξη και ρύθμιση εταιρείας","description":"","frontmatter":{},"headers":[],"relativePath":"el/getting-started/company-onboarding.md","filePath":"el/getting-started/company-onboarding.md"}'),n={name:"el/getting-started/company-onboarding.md"};function o(i,t,l,s,h,p){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ενταξη-και-ρυθμιση-εταιρειας" tabindex="-1">Ένταξη και ρύθμιση εταιρείας <a class="header-anchor" href="#ενταξη-και-ρυθμιση-εταιρειας" aria-label="Permalink to &quot;Ένταξη και ρύθμιση εταιρείας&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Οδηγίες βάσει v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, δικαιώματα και εγκεκριμένο εύρος. Η εκπαίδευση χρησιμοποιεί εγκεκριμένα συνθετικά δεδομένα· δεν εγκρίνεται εμπορική ενεργοποίηση.</p></div><h2 id="προετοιμασια-εταιρειας" tabindex="-1">Προετοιμασία εταιρείας <a class="header-anchor" href="#προετοιμασια-εταιρειας" aria-label="Permalink to &quot;Προετοιμασία εταιρείας&quot;">​</a></h2><p>Επιβεβαιώστε εγκεκριμένη έκδοση, εξουσιοδοτημένο διαχειριστή και υπεύθυνο υποστήριξης. Στο Company Settings εξετάστε τη λίστα ένταξης. Ο κώδικας v0.7.26 ελέγχει οκτώ απαιτούμενους τομείς:</p><table tabindex="0"><thead><tr><th>Τομέας</th><th>Κριτήριο λίστας</th><th>Ανεξάρτητος έλεγχος</th></tr></thead><tbody><tr><td>Ταυτότητα</td><td>Εμπορική επωνυμία, νομική οντότητα, ΑΦΜ</td><td>Ορθότητα βάσει εγκεκριμένων στοιχείων</td></tr><tr><td>Αγορές</td><td>Τουλάχιστον μία ενεργή</td><td>Ζώνη ώρας και πραγματική κάλυψη</td></tr><tr><td>Τοποθεσίες</td><td>Τουλάχιστον δύο μη απενεργοποιημένες</td><td>Έγκυρα σημεία διαδρομής ανά αγορά</td></tr><tr><td>Στόλος</td><td>Τουλάχιστον μία κατηγορία και μη αρχειοθετημένο όχημα</td><td>Χωρητικότητα, διαθεσιμότητα, συντήρηση</td></tr><tr><td>Οδηγοί</td><td>Τουλάχιστον ένας μη αρχειοθετημένος</td><td>Βάρδια, σύνδεση λογαριασμού και πρόσβαση</td></tr><tr><td>Τιμολόγηση</td><td>Θετική τιμή διαδρομής/ώρας ή πολλαπλασιαστής κατηγορίας</td><td>Έγκυρη προσφορά ανά υπηρεσία</td></tr><tr><td>Κανάλια</td><td>Τουλάχιστον ένα ενεργό</td><td>Domain, δημοσίευση και ανεξάρτητοι διακόπτες λήψης</td></tr><tr><td>Διακανονισμός</td><td>Νόμισμα, ζώνη ώρας και περιθώριο τουλάχιστον 15 λεπτών</td><td>Πραγματική αποδοχή πληρωμών και αναθέσεων</td></tr></tbody></table><p>Η πλήρης λίστα ρυθμίσεων δεν αποτελεί επιχειρησιακή αποδοχή. Ο αριθμός τοποθεσιών δεν αποδεικνύει κάλυψη διαδρομών· ο πολλαπλασιαστής δεν εγγυάται έγκυρο ναύλο· η ένδειξη καναλιού δεν ενεργοποιεί δημόσια λήψη. Ο αριθμός οδηγών δεν αποδεικνύει σύνδεση λογαριασμού. Η ετοιμότητα demo δεν είναι εμπορική ετοιμότητα.</p><p>Συνιστώνται ωριαίες και εποχικές τιμές, εκδρομές, συνεργάτες, πρότυπα μηνυμάτων, εταιρική εικόνα και χρήστες. Τα πρόσθετα στοιχεία εξαρτώνται από διαθέσιμα δεδομένα. Αν δεν υπάρχει αριθμός χρηστών, ο κώδικας μπορεί να συμπεράνει ετοιμότητα ομάδας από εταιρική ταυτότητα· ελέγξτε πραγματικούς λογαριασμούς.</p><h2 id="σειρα-ρυθμισης" tabindex="-1">Σειρά ρύθμισης <a class="header-anchor" href="#σειρα-ρυθμισης" aria-label="Permalink to &quot;Σειρά ρύθμισης&quot;">​</a></h2><p>Ολοκληρώστε ταυτότητα, αγορές, τοποθεσίες, στόλο, οδηγούς, ναύλους και κανάλια. Επιβεβαιώστε πολιτική διακανονισμού και ατομικούς λογαριασμούς. Εξετάστε προαιρετικές υπηρεσίες μόνο αν πωλούνται. Δοκιμάστε με συνθετικά στοιχεία την <a href="/el/getting-started/first-reservation.html">πρώτη κράτηση</a> και τη <a href="/el/getting-started/go-live-checklist.html">λίστα έναρξης</a>. Διατηρήστε εξωτερικούς παρόχους και δημόσια λήψη ανενεργούς χωρίς χωριστή έγκριση.</p><p>Δείτε <a href="/el/plus/company-and-language-settings.html">Ρυθμίσεις</a>, <a href="/el/plus/staff-administration.html">Προσωπικό</a> και <a href="/el/integrations/third-party-api-setup.html">API τρίτων</a>.</p>',10)])])}const g=a(n,[["render",o]]);export{m as __pageData,g as default};
